/* ---------------- Icon (real illustration assets) ---------------- */
function Icon({ name, size = 72, alt = "" }) {
  if (!name || !ICONS[name]) return null;
  return (
    <img
      src={ICONS[name]}
      alt={alt}
      draggable={false}
      style={{ width: size, height: "auto", display: "block", userSelect: "none" }}
    />
  );
}

/* ---------------- Small UI atoms ---------------- */
function PrimaryButton({ children, onClick, style, narrow }) {
  return (
    <button className={"btn-primary" + (narrow ? " btn-primary--narrow" : "")} onClick={onClick} style={style}>
      {children}
    </button>
  );
}
function GhostButton({ children, onClick, active, narrow }) {
  return (
    <button className={"btn-ghost" + (active ? " btn-ghost--active" : "") + (narrow ? " btn-ghost--narrow" : "")} onClick={onClick}>
      {children}
    </button>
  );
}
function BackChevron({ onClick }) {
  return (
    <button className="back-chevron" onClick={onClick} aria-label="Volver">
      <Icon name="back_arrow" size={30} />
    </button>
  );
}
function HomeDock({ onClick }) {
  return (
    <button className="home-dock" onClick={onClick} aria-label="Ir al inicio">
      <Icon name="home_icon" size={44} />
    </button>
  );
}

